ALTER COLUMN "city_id" SET DATA TYPE TEXT,
ADD CONSTRAINT "districts_pkey" PRIMARY KEY ("id");

-- AlterTable
ALTER TABLE "sub_districts" DROP CONSTRAINT "sub_districts_pkey",
ALTER COLUMN "id" SET DATA TYPE TEXT,
ALTER COLUMN "district_id" SET DATA TYPE TEXT,
ADD CONSTRAINT "sub_districts_pkey" PRIMARY KEY ("id");

-- AlterTable
ALTER TABLE "checkout_drafts" ALTER COLUMN "province_id" SET DATA TYPE TEXT,
ALTER COLUMN "city_id" SET DATA TYPE TEXT,
ALTER COLUMN "district_id" SET DATA TYPE TEXT,
ALTER COLUMN "sub_district_id" SET DATA TYPE TEXT;

