-- Step 2: move the regions loaded by the earlier seed (ids 1, 2, 3 ...) to their wilayah.id codes.
-- Every foreign key above is ON UPDATE CASCADE, so shops, checkout drafts and saved addresses that
-- point at these regions move with them. On a new, empty database these updates change nothing.
UPDATE "provinces" AS r SET "id" = m.new_id
FROM (VALUES
  ('1', '31'),
  ('2', '32'),
  ('3', '51')
) AS m(old_id, new_id)
WHERE r."id" = m.old_id;

UPDATE "cities" AS r SET "id" = m.new_id
FROM (VALUES
  ('1', '3174'),
  ('2', '3171'),
  ('3', '3273'),
  ('4', '3201'),
  ('5', '5171')
) AS m(old_id, new_id)
WHERE r."id" = m.old_id;

UPDATE "districts" AS r SET "id" = m.new_id
FROM (VALUES
  ('1', '317407'),
  ('2', '317401'),
  ('3', '317106'),
  ('4', '317101'),
  ('5', '327302'),
  ('6', '327306'),
  ('7', '320101'),
  ('8', '320107'),
  ('9', '517101'),
  ('10', '517103')
) AS m(old_id, new_id)
WHERE r."id" = m.old_id;

UPDATE "sub_districts" AS r SET "id" = m.new_id
FROM (VALUES
  ('1', '3174071002'),
  ('2', '3174071006'),
  ('3', '3174071001'),
  ('4', '3174011002'),
  ('5', '3174011001'),
  ('6', '3171061001'),
  ('7', '3171061002'),
  ('8', '3171011001'),
  ('9', '3171011004'),
  ('10', '3273021004'),
  ('11', '3273021006'),
  ('12', '3273061002'),
  ('13', '3273061001'),
  ('14', '3201011007'),
  ('15', '3201011003'),
  ('16', '3201072012'),
  ('17', '3201072011'),
  ('18', '5171011006'),
  ('19', '5171011002'),
  ('20', '5171031007'),
  ('21', '5171031005')
) AS m(old_id, new_id)
WHERE r."id" = m.old_id;

-- Step 3: every code has its level's length and starts with its parent's code.
ALTER TABLE "provinces" ADD CONSTRAINT "provinces_id_code" CHECK ("id" ~ '^[0-9]{2}$');
ALTER TABLE "cities" ADD CONSTRAINT "cities_id_code" CHECK ("id" ~ '^[0-9]{4}$' AND left("id", 2) = "province_id");
ALTER TABLE "districts" ADD CONSTRAINT "districts_id_code" CHECK ("id" ~ '^[0-9]{6}$' AND left("id", 4) = "city_id");
ALTER TABLE "sub_districts" ADD CONSTRAINT "sub_districts_id_code" CHECK ("id" ~ '^[0-9]{10}$' AND left("id", 6) = "district_id");
